// src/jsx/PrivateChat.jsx
import React, { useEffect, useState, useRef } from "react";
import { db } from "../js/firebaseConfig";
import { collection, addDoc, serverTimestamp, query, orderBy, onSnapshot, doc, setDoc, getDoc } from "firebase/firestore";

function makeRoomId(a, b) {
    return [a, b].sort().join("_");
}

export default function PrivateChat({ currentUser, otherUser, onClose }) {
    const roomId = makeRoomId(currentUser.uid, otherUser.id);
    const [messages, setMessages] = useState([]);
    const [text, setText] = useState("");
    const messagesRef = collection(db, `rooms/${roomId}/messages`);
    const listRef = useRef(null);
    const [screen, setScreen] = useState("contacts"); 
    const [chatUser, setChatUser] = useState(null);
    const [chatGroup, setChatGroup] = useState(null);

    useEffect(() => {
        // create room doc if not exists (with members)
        const roomDocRef = doc(db, "rooms", roomId);
        getDoc(roomDocRef).then(snap => {
            if (!snap.exists()) {
                setDoc(roomDocRef, { members: [currentUser.uid, otherUser.id], createdAt: serverTimestamp(), lastMessage: "" });
            }
        });

        const q = query(messagesRef, orderBy("createdAt", "asc"));
        const unsub = onSnapshot(q, (snap) => {
            setMessages(snap.docs.map(d => ({ id: d.id, ...d.data() })));
            // scroll
            setTimeout(() => { if (listRef.current) listRef.current.scrollTop = listRef.current.scrollHeight; }, 100);
        });
        return () => unsub();
    }, [roomId]);

    const send = async () => {
        if (!text.trim()) return;
        await addDoc(messagesRef, { text, from: currentUser.uid, createdAt: serverTimestamp() });
        // update room lastMessage
        const roomDocRef = doc(db, "rooms", roomId);
        await setDoc(roomDocRef, { lastMessage: text, lastUpdated: serverTimestamp() }, { merge: true });
        setText("");
    };

    return (
        <div className="chat-container">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <h4>Chat com {otherUser.nome || otherUser.email}</h4>
                <button onClick={onClose}>Fechar</button>
            </div>

            <div className="chat-box" ref={listRef} style={{ height: 300 }}>
                {messages.map(m => (
                    <div key={m.id} style={{ padding: 6, textAlign: m.from === currentUser.uid ? "right" : "left" }}>
                        <div style={{ display: "inline-block", background: m.from === currentUser.uid ? "#DCF8C6" : "#eee", padding: 8, borderRadius: 8 }}>
                            {m.text}
                        </div>
                    </div>
                ))}
            </div>

            <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                <input value={text} onChange={e => setText(e.target.value)} placeholder="Escreva..." />
                <button onClick={send}>Enviar</button>
            </div>
        </div>
    );
}
